from collections import Counter
from heapq import nsmallest

_RX = re.compile('[a-z]+')

def top_words(text, k):
    """The k most common words. A word is a run of the letters a-z after
    lower-casing; every other character separates words.
    Ties: alphabetical order. Returns a list of (word, count)."""
    try:
        n = int(k)
    except Exception:
        n = k
    counts = Counter(_RX.findall(text.lower()))
    if n <= 0:
        # match original pairs[:k] semantics for k <= 0
        if n == 0:
            return []
        return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:n]
    return nsmallest(n, counts.items(), key=lambda kv: (-kv[1], kv[0]))
